INSERT INTO qr_word_sense_link (id, word_occ_id, al_sense_id, al_arc_id, surah_no, ayah_no, word_index, ayah_key, is_contextual, is_primary, display_order, evidence_json, confidence, status) VALUES ('WSL:18:86:14:say_wordless', '63f2680087c02101ec3aff6f43', 'SNS:قول:say_wordless', NULL, 18, 86, 14, '18:86', 1, 1, 1, '[{"kind": "lexicon", "slug": "raghib_mufradat", "ref": "blk_mfr_ba31652f5d2bea11", "quote_ar": "فإنّ ذلك لم يكن بخطاب ورد عليه فيما روي وذكر، بل كان ذلك إلهاما فسماه قولا", "agreement": "supports"}, {"kind": "tafsir", "slug": "razi", "ref": "QR:TE:2e46bdeff0da54ec08ff61cc", "quote_ar": "يَدُلُّ عَلى أنَّهُ تَعالى تَكَلَّمَ مَعَهُ مِن غَيْرِ واسِطَةٍ، وذَلِكَ يَدُلُّ عَلى أنَّهُ كانَ نَبِيًّا", "agreement": "contests"}]', 'medium', 'live');
INSERT INTO qr_word_sense_link (id, word_occ_id, al_sense_id, al_arc_id, surah_no, ayah_no, word_index, ayah_key, is_contextual, is_primary, display_order, evidence_json, confidence, status) VALUES ('WSL:21:69:1:say_wordless', '2098ee33f6d01308b939b61c6e', 'SNS:قول:say_wordless', NULL, 21, 69, 1, '21:69', 1, 1, 1, '[{"kind": "lexicon", "slug": "raghib_mufradat", "ref": "blk_mfr_66784d64bcaf9ae7", "quote_ar": "إنّ ذلك كان بتسخير من الله تعالى لا بخطاب ظاهر ورد عليهما، وكذا قوله تعالى: قُلْنا يا نارُ كُونِي بَرْداً وَسَلاماً", "agreement": "supports"}]', 'medium', 'live');
INSERT INTO qr_word_sense_link (id, word_occ_id, al_sense_id, al_arc_id, surah_no, ayah_no, word_index, ayah_key, is_contextual, is_primary, display_order, evidence_json, confidence, status) VALUES ('WSL:41:11:7:say_wordless', '89fb6a307d641528e226ae32b4', 'SNS:قول:say_wordless', NULL, 41, 11, 7, '41:11', 1, 1, 1, '[{"kind": "tafsir", "slug": "ibn_ashur", "ref": "QR:TE:96a227fab748d33525c6d943", "quote_ar": "وهو قَوْلُ تَكْوِينٍ", "agreement": "supports"}, {"kind": "tafsir", "slug": "zamakhshari", "ref": "QR:TE:e699c665aa429b0ae9e8ed22", "quote_ar": "من غير أن يحقق شيء من الخطاب والجواب", "agreement": "supports"}]', 'medium', 'live');
