INSERT INTO qr_word_sense_link (id, word_occ_id, al_sense_id, al_arc_id, surah_no, ayah_no, word_index, ayah_key, is_contextual, is_primary, display_order, evidence_json, confidence, status) VALUES ('WSL:69:44:2:forge', '9edb8642c82c5e24a88a1652dd', 'SNS:قول:forge', NULL, 69, 44, 2, '69:44', 1, 1, 1, '[{"kind": "lexicon", "slug": "ibn_manzur_lisan_arab", "ref": "blk_lsn_21f08641a3972f36", "quote_ar": "وتَقَوَّلَ قَوْلًا: ابتدَعه كذِباً. وتَقَوَّلَ فُلَانٌ عليَّ بَاطِلًا أَي قَالَ عَليَّ مَا لَمْ أَكن قلتُ وَكَذِبَ عليَّ؛ وَمِنْهُ قَوْلُهُ تَعَالَى: وَلَوْ تَقَوَّلَ عَلَيْنا بَعْضَ الْأَقاوِيلِ", "agreement": "supports"}, {"kind": "tafsir", "slug": "tabari", "ref": "QR:TE:ee28f1682138094ca97c2e5f", "quote_ar": "الباطلة، وتكذب علينا", "agreement": "supports"}]', 'high', 'live');
INSERT INTO qr_word_sense_link (id, word_occ_id, al_sense_id, al_arc_id, surah_no, ayah_no, word_index, ayah_key, is_contextual, is_primary, display_order, evidence_json, confidence, status) VALUES ('WSL:69:44:5:sayings', 'ea9454b29b7d46138ce5b6ecd6', 'SNS:قول:sayings', NULL, 69, 44, 5, '69:44', 1, 1, 1, '[{"kind": "lexicon", "slug": "ibn_manzur_lisan_arab", "ref": "blk_lsn_a9abb665776f8d2a", "quote_ar": "وَالْجَمْعُ أَقْوال، وأَقاوِيل جَمْعُ الْجَمْعِ", "agreement": "supports"}, {"kind": "tafsir", "slug": "zamakhshari", "ref": "QR:TE:176eecc4c90171accb45a2a0", "quote_ar": "وسمى الأقوال المتقولة «أقاويل» تصغيرا بها وتحقيرا", "agreement": "supports"}]', 'high', 'live');
